import sys; sys.path.insert(0, sys.argv[1]); from story import *
N = "TOEIC Part 7 式的阅读：先看题目再读文章，带着问题找答案。先关掉译文读。"
if "en.2.1" in sys.argv[2:]:
  STORY("en.2.1", "A Busy Monday", N, [
   ("To: All Marketing Staff", "收件人：市场部全体员工"),
   ("From: Diane Cole, Office Manager", "发件人：办公室经理黛安·科尔"),
   ("Subject: This week's schedule changes", "主题：本周日程变更"), "",
   ("I'm writing to let you know about some changes to this week's schedule.", "特此告知本周日程的几项变更。"),
   ("First, Tuesday's team meeting has been postponed until Thursday at 10 a.m. because Mr. Hill is visiting a client in Boston.", "第一，周二的团队会议推迟到周四上午十点，因为希尔先生要去波士顿拜访客户。"),
   ("The updated agenda is attached. Please read it prior to the meeting.", "更新后的议程见附件，请在会前阅读。"),
   ("Second, the copier on the third floor is out of order.", "第二，三楼的复印机坏了。"),
   ("A technician will repair it on Wednesday. Until then, please use the one next to the reception desk.", "技术员周三来修。在那之前，请使用前台旁边的那台。"), "",
   ("Finally, two interns will join our team as of next Monday.", "最后，从下周一起，两名实习生将加入我们团队。"),
   ("They will sit in the empty cubicles near the window.", "他们会坐在窗边的空隔间。"),
   ("If you can help them during their first week, please let me know.", "如果你在他们第一周能帮忙带一带，请告诉我。"),
   ("Thank you for your cooperation.", "感谢配合。")],
   [Q("What is the main purpose of the e-mail?", ["To announce changes to the schedule", "To introduce a new manager", "To ask staff to work overtime"], "I'm writing to let you know about some changes to this week's schedule. —— 目的句在开头。"),
    Q("Why was the team meeting postponed?", ["A manager is visiting a client.", "The meeting room is being repaired.", "The agenda is not ready."]),
    Q("What are staff asked to do before the meeting?", ["Read the agenda", "Call Mr. Hill", "Fix the copier"], "Please read it prior to the meeting. —— prior to = before。"),
    Q("Where should staff make copies on Tuesday?", ["Next to the reception desk", "On the third floor", "In Boston"]),
    Q("The word “as of” in paragraph 2 is closest in meaning to", ["starting", "because of", "instead of"], "as of next Monday = 从下周一起。Part 7 常考这种同义替换。"),
    TR("会议推迟到周四了。", ["The meeting has been postponed until Thursday.", "The meeting was postponed until Thursday.", "The meeting has been put off until Thursday."])],
   ["Part 7 解题法：第一题问目的 → 看第一段 I'm writing to …。", "同义替换：postponed = put off / delayed；prior to = before；as of = starting。", "本单元词：agenda、copier、technician、intern、cubicle、cooperation。"])
if "en.2.2" in sys.argv[2:]:
  STORY("en.2.2", "Morning at the Harbor", "一段“文字照片”：读的时候在脑子里画出画面，再判断哪些描述能从“照片”里看出来。", [
   ("It is early morning at a small harbor.", "清晨，一个小港口。"),
   ("Several fishing boats are tied up in a row along the pier.", "几艘渔船沿着码头排成一排系着。"),
   ("On the closest boat, a man is unloading crates of fish.", "最近的那艘船上，一名男子正在卸一箱箱的鱼。"),
   ("Another man is standing on the pier and lifting the crates onto a cart.", "另一名男子站在码头上，把箱子搬到推车上。"), "",
   ("A woman in a yellow jacket is leaning on the railing.", "一位穿黄色外套的女士靠在栏杆上。"),
   ("She is looking at the boats and holding a cup of coffee.", "她一边看着船，一边端着一杯咖啡。"),
   ("Behind her, some tables and chairs have been set up in front of a small café.", "她身后，一家小咖啡馆门前摆好了一些桌椅。"),
   ("The café is not open yet, and no one is sitting outside.", "咖啡馆还没开门，外面没有人坐着。"), "",
   ("Far away, a large vessel is sailing out of the harbor.", "远处，一艘大船正驶出港口。"),
   ("A few seagulls are flying above the water.", "几只海鸥在水面上飞。")],
   [Q("Which sentence matches the scene?", ["Some boats are tied up in a row.", "Some boats are being painted.", "The pier is crowded with tourists."]),
    Q("What is the woman doing?", ["Leaning on a railing", "Serving coffee in a café", "Unloading crates"]),
    Q("Which sentence is NOT true?", ["Some customers are sitting outside the café.", "Tables and chairs have been set up.", "A vessel is sailing out of the harbor."], "The café is not open yet, and no one is sitting outside. —— 没有人坐着。"),
    Q("\"Some tables and chairs have been set up\" describes", ["物品已经摆好的状态", "有人正在摆桌椅", "桌椅将要被摆放"], "has / have been done = 已被……（状态）。"),
    TR("一名男子正在卸一箱箱的鱼。", ["A man is unloading crates of fish.", "A man is unloading some crates of fish."])],
   ["Part 1 语言：is unloading / is leaning on / have been set up / are tied up in a row。", "人物照用 is doing；物品状态用 has been done。", "词：pier、crate、railing、vessel、in a row。"])
if "en.2.3" in sys.argv[2:]:
  STORY("en.2.3", "A Defective Order", N, [
   ("To: Customer Service, Brightway Office Supplies", "收件人：Brightway 办公用品公司客服部"),
   ("Subject: Order #4471", "主题：订单 #4471"), "",
   ("I'm writing about the order I placed on May 3.", "我写信是关于我 5 月 3 日下的订单。"),
   ("The shipment arrived yesterday, but two of the ten desk lamps are defective. They do not turn on.", "货昨天到了，但十盏台灯中有两盏是坏的，打不开。"),
   ("Also, one box was marked \"fragile,\" but it was damaged when it arrived.", "另外，有一个箱子标着“易碎”，到货时却已经破损。"),
   ("Could you send two replacements as soon as possible? We need them for a new office that opens on May 20.", "能否尽快寄两盏替换的？5 月 20 日开业的新办公室要用。"),
   ("Kevin Ross, Office Manager", "凯文·罗斯，办公室经理"), "",
   ("Dear Mr. Ross,", "罗斯先生："),
   ("We apologize for the inconvenience.", "给您带来不便，我们深表歉意。"),
   ("Two replacement lamps were dispatched this morning by express courier, and your tracking number is BW-2281.", "两盏替换台灯已于今早通过快递寄出，追踪号为 BW-2281。"),
   ("You do not need to return the defective items.", "您无需退回有问题的商品。"),
   ("To compensate you for the trouble, we have also attached a voucher for 15% off your next order.", "为补偿给您带来的麻烦，我们还附上了一张下次订单八五折的优惠券。")],
   [Q("Why did Mr. Ross write the first e-mail?", ["Some items he received were defective.", "He wanted to cancel an order.", "He needed a new catalog."]),
    Q("When does the new office open?", ["On May 20", "On May 3", "Tomorrow"]),
    Q("What does the company ask Mr. Ross to do with the defective lamps?", ["Nothing; he can keep them.", "Send them back by courier.", "Take them to a store."], "You do not need to return the defective items."),
    Q("What does the company offer Mr. Ross?", ["A discount on his next order", "A full refund", "A free desk"], "a voucher for 15% off your next order —— 同义替换成 discount。"),
    Q("The word \"dispatched\" is closest in meaning to", ["sent", "repaired", "ordered"]),
    TR("给您带来不便，我们深表歉意。", ["We apologize for the inconvenience.", "We are sorry for the inconvenience."])],
   ["Part 7 双邮件：先读第一封抓问题，再在第二封里找解决办法。", "同义替换：dispatched = sent；voucher for 15% off = discount。", "词：shipment、defective、fragile、replacement、courier、tracking number、compensate、voucher。"])
if "en.2.4" in sys.argv[2:]:
  STORY("en.2.4", "Notice: Changes to the Expense Policy", N, [
   ("To all employees:", "全体员工："),
   ("As of July 1, a new expense policy will be implemented across the company.", "自 7 月 1 日起，全公司将实施新的报销制度。"),
   ("The goal is to streamline the reimbursement process and reduce paperwork.", "目的是简化报销流程，减少文书工作。"), "",
   ("Under the new policy, all expenses must be itemized and submitted online within ten days.", "按照新制度，所有费用必须逐项列明，并在十天内在线提交。"),
   ("Receipts are mandatory for any single item that exceeds fifty dollars.", "单项超过五十美元必须附收据。"),
   ("Each request will be verified by the accounting department before payment is made.", "每份申请在付款前都会由会计部核实。"), "",
   ("Although most employees have used the old paper forms for years, the new system is user-friendly.", "虽然大多数员工多年来一直用纸质表格，但新系统使用起来很方便。"),
   ("A short training session will be held in the main conference room on June 25.", "6 月 25 日将在大会议室举办一次简短培训。"),
   ("Attendance is not required, but it is highly recommended.", "不强制参加，但强烈推荐。"),
   ("Questions about the policy should be directed to Ms. Rivera in Accounting.", "关于该制度的问题请咨询会计部的里维拉女士。")],
   [Q("What is the purpose of the notice?", ["To announce a new expense policy", "To introduce a new accountant", "To cancel a training session"]),
    Q("What must employees do for items over fifty dollars?", ["Submit a receipt", "Get a manager's signature", "Pay in cash"]),
    Q("Who will verify the requests?", ["The accounting department", "Each employee's manager", "Ms. Rivera's assistant"]),
    Q("What is true about the training session?", ["It is optional.", "It is mandatory for all staff.", "It will be held online."], "Attendance is not required —— 选项把它换成了 optional。"),
    Q("The word \"streamline\" in line 3 is closest in meaning to", ["simplify", "delay", "describe"]),
    TR("所有费用必须逐项列明。", ["All expenses must be itemized.", "All the expenses must be itemized."])],
   ["Part 5 的词性、语态在真实通知里：will be implemented / must be itemized / will be verified。", "同义替换：not required = optional；streamline = simplify。", "词：as of、implement、streamline、itemize、mandatory、exceed、verify、user-friendly。"])
